import re
lines = open('/app/text.gcode').read().splitlines()

chunks = []
cur = None
for i, ln in enumerate(lines, 1):
    s = ln.strip()
    if s.startswith('M486 S0'):
        cur = i+1  # content starts after
    elif s.startswith('M486 S-1') and cur is not None:
        chunks.append((cur, i-1))
        cur = None
print("num chunks:", len(chunks))

def parse(ln):
    x=y=z=e=None
    for tok in ln.split():
        if tok[0]=='X': x=float(tok[1:])
        elif tok[0]=='Y': y=float(tok[1:])
        elif tok[0]=='Z': z=float(tok[1:])
        elif tok[0]=='E':
            try: e=float(tok[1:])
            except: e=None
    return x,y,z,e

for (a,b) in chunks:
    # read content
    xs=[]; ys=[]; zs=[]
    import re
    for ln in lines[a-1:b]:
        if ln.lstrip().startswith(('G1','G0')):
            x,y,z,e = parse(ln.lstrip())
            if x is not None: xs.append(x)
            if y is not None: ys.append(y)
            if z is not None: zs.append(z)
    if xs and ys:
        print(f"lines {a}-{b} n={len(xs)} X[{min(xs):.2f},{max(xs):.2f}] Y[{min(ys):.2f},{max(ys):.2f}] Z[{min(zs):.2f},{max(zs):.2f}]")
