{"description":"Render a few specific Z layers to see how shapes vary with height","cmd":"python3 - <<'EOF'
lines = open('/app/text.gcode').read().splitlines()

def parse(ln):
    d={}
    for tok in ln.split():
        c=tok[0]
        if c in 'XYZEF':
            try: d[c]=float(tok[1:])
            except: pass
    return d

segs=[]
pos={'X':0,'Y':0,'Z':0,'E':0}
for i in range(15014-1, 98473):
    s=lines[i].lstrip()
    if not s.startswith(('G1','G0')): continue
    d=parse(s)
    has_xy = 'X' in d or 'Y' in d
    if has_xy:
        px,py,pz = pos['X'],pos['Y'],pos['Z']
        e0 = pos['E']
        nx = d.get('X', px); ny = d.get('Y', py)
        nz = d.get('Z', pz)
        if 'E' in d and d['E'] > e0 + 1e-9:
            segs.append((px,py,nx,ny,pz,nz))
        pos['X'],pos['Y'],pos['Z'] = nx,ny,nz
    if 'E' in d:
        pos['E']=d['E']

def render_at(z_target, tol=0.10, res=0.5, name='r'):
    sel=[s for s in segs if abs(s[4]-z_target)<tol]
    if not sel: print("no segs at", z_target); return
    xs=[p for s in sel for p in [s[0],s[2]]]; ys=[p for s in sel for p in [s[1],s[3]]]
    x0,x1=min(xs),max(xs); y0,y1=min(ys),max(ys)
    W=int((x1-x0)/res)+2; H=int((y1-y0)/res)+2
    grid=[[0]*W for _ in range(H)]
    def raster(a,b,c,d_):
        ax=(a-x0)/res; ay=(b-y0)/res; bx=(c-x0)/res; by=(d_-y0)/res
        dx=bx-ax; dy=by-ay; steps=max(abs(dx),abs(dy))
        if steps==0:
            px=int(round(ax)); py=int(round(ay))
            if 0<=px<W and 0<=py<H: grid[py][px]=1
            return
        for i in range(int(steps)+1):
            t=i/steps
            px=int(round(ax+dx*t)); py=int(round(ay+dy*t))
            if 0<=px<W and 0<=py<H: grid[py][px]=1
    for s in sel: raster(s[0],s[1],s[2],s[3])
    out=[''.join('#' if v else '.' for v in row).rstrip('.') for row in grid]
    # trim leading/trailing empty rows
    nonempty=[r for r in out if r.strip('.')]
    print(f"--- Z={z_target} segs={len(sel)} grid {H}x{W} ---")
    print('\n'.join(nonempty))

for z in [3.0, 30.0, 50.0, 60.0]:
    render_at(z)
EOF"}

