            segs.append((px,py,nx,ny,pz,nz))
        pos['X'],pos['Y'],pos['Z'] = nx,ny,nz
    if 'E' in d:
        pos['E']=d['E']

def slice_fill(zlo, zhi, res=0.45):
    sel=[s for s in segs if zlo<=s[4]<=zhi]
    if not sel: print("empty", zlo, zhi); return None
    xs=[p for s in sel for p in [s[0],s[2]]]; ys=[p for s in sel for p in [s[1],s[3]]]
    x0,x1=min(xs),max(xs); y0,y1=min(ys),max(ys)
    # use fixed window across object for comparability
    ax0,ax1,ay0,ay1 = 55.0,205.0,79.0,148.0
    W=int((ax1-ax0)/res)+2; H=int((ay1-ay0)/res)+2
    grid=[[' ']*W for _ in range(H)]
    def put(a,b,c,d_):
        pax=(a-ax0)/res; pay=(b-ay0)/res; pbx=(c-ax0)/res; pby=(d_-ay0)/res
        dx=pbx-pax; dy=pby-pay; steps=max(abs(dx),abs(dy))
        if steps<1e-9:
            px=int(round(pax)); py=int(round(pay))
            if 0<=px<W and 0<=py<H: grid[py][px]='#'
            return
        for i in range(int(steps)+1):
            t=i/steps
            px=int(round(pax+dx*t)); py=int(round(pay+dy*t))
            if 0<=px<W and 0<=py<H: grid[py][px]='#'
    for s in sel: put(s[0],s[1],s[2],s[3])
    # trim
    out=[''.join(r).rstrip() for r in grid]
    while out and not out[0].strip(): out.pop(0)
    while out and not out[-1].strip(): out.pop()
    return out

for (zlo,zhi) in [(0,5),(8,12),(20,30),(40,50),(60,65)]:
    out=slice_fill(zlo,zhi)
    if out is None: continue
    print(f"=== Z in [{zlo},{zhi}] ({len(out)} rows) ===")
    print('\n'.join(out))
EOF"}

